#!/usr/bin/env bash
#
# Verify Tauri capability configuration by parsing actual source files.
#
# This script checks that:
# 1. build.rs COMMANDS matches registered invoke_handler commands
# 2. capabilities/*.json partition matches COMMANDS exactly
# 3. autogenerated permissions match COMMANDS exactly
# 4. No drift between frontend invoke and backend commands
# 5. Capability schema validates via cargo check
#
# Usage:
#   scripts/verify-tauri-capabilities.sh
#
# Exit codes:
#   0 - All checks pass
#   1 - Verification failed
set -euo pipefail

cd "$(dirname "$0")/.."

errors=0

printf 'Verifying Tauri capability configuration...\n\n'

# 1. Extract COMMANDS from build.rs
printf '1. Extracting COMMANDS from build.rs... '
if [[ ! -f "apps/lens/build.rs" ]]; then
  printf 'FAILED (build.rs not found)\n'
  exit 1
fi

# Parse the COMMANDS array from build.rs
build_commands=$(grep -A 100 'const COMMANDS:' apps/lens/build.rs | \
  grep -oE '"[a-z_]+"' | tr -d '"' | sort)
build_count=$(echo "$build_commands" | wc -l)

if [[ $build_count -lt 40 ]]; then
  printf 'FAILED (only %d commands, expected >= 40)\n' "$build_count"
  errors=$((errors + 1))
else
  printf 'OK (%d commands)\n' "$build_count"
fi

# 2. Extract registered invoke_handler commands from tauri_app.rs
printf '2. Extracting registered commands from tauri_app.rs... '
if [[ ! -f "apps/lens/src/tauri_app.rs" ]]; then
  printf 'FAILED (tauri_app.rs not found)\n'
  exit 1
fi

# Parse invoke_handler commands
registered_commands=$(grep -A 100 'invoke_handler' apps/lens/src/tauri_app.rs | \
  grep -B 100 '\])' | grep -oE '[a-z_]+,' | tr -d ',' | sort)
registered_count=$(echo "$registered_commands" | wc -l)

if [[ $registered_count -lt 40 ]]; then
  printf 'FAILED (only %d registered, expected >= 40)\n' "$registered_count"
  errors=$((errors + 1))
else
  printf 'OK (%d commands)\n' "$registered_count"
fi

# 3. Check build.rs COMMANDS == registered commands
printf '3. Checking COMMANDS == registered commands... '
if [[ "$build_commands" == "$registered_commands" ]]; then
  printf 'OK (exact match)\n'
else
  printf 'FAILED (drift detected)\n'
  diff <(echo "$build_commands") <(echo "$registered_commands") | head -10
  errors=$((errors + 1))
fi

# 4. Extract capability permissions
printf '4. Extracting capability permissions... '
main_perms=$(grep -oE '"allow-[a-z-]+"' apps/lens/capabilities/main.json | \
  sed 's/"allow-//;s/"//;s/-/_/g' | sort)
detail_perms=$(grep -oE '"allow-[a-z-]+"' apps/lens/capabilities/detail.json | \
  sed 's/"allow-//;s/"//;s/-/_/g' | sort)

main_count=$(echo "$main_perms" | wc -l)
detail_count=$(echo "$detail_perms" | wc -l)

printf 'OK (main: %d, detail: %d)\n' "$main_count" "$detail_count"

# 5. Check main ∪ detail == COMMANDS
printf '5. Checking main ∪ detail == COMMANDS... '
all_caps=$(echo -e "$main_perms\n$detail_perms" | sort -u)
if [[ "$all_caps" == "$build_commands" ]]; then
  printf 'OK (exact partition)\n'
else
  printf 'FAILED (partition mismatch)\n'
  echo "Missing from capabilities:"
  comm -23 <(echo "$build_commands") <(echo "$all_caps")
  echo "Extra in capabilities:"
  comm -13 <(echo "$build_commands") <(echo "$all_caps")
  errors=$((errors + 1))
fi

# 6. Check main ∩ detail == empty
printf '6. Checking main ∩ detail == empty... '
overlap=$(comm -12 <(echo "$main_perms") <(echo "$detail_perms"))
if [[ -z "$overlap" ]]; then
  printf 'OK (no overlap)\n'
else
  printf 'FAILED (overlap detected)\n'
  echo "$overlap"
  errors=$((errors + 1))
fi

# 7. Check detail only has detail_* commands
printf '7. Checking detail only has detail_* commands... '
non_detail=$(echo "$detail_perms" | grep -v '^detail_' || true)
if [[ -z "$non_detail" ]]; then
  printf 'OK\n'
else
  printf 'FAILED (non-detail commands in detail.json)\n'
  echo "$non_detail"
  errors=$((errors + 1))
fi

# 8. Check high-risk commands not in detail
printf '8. Checking high-risk commands excluded from detail... '
high_risk="library_secure_wipe request_quit set_autostart save_settings mori_send_item"
leaked=0
for cmd in $high_risk; do
  if echo "$detail_perms" | grep -q "^${cmd}$"; then
    printf '\n  - leaked: %s' "$cmd"
    leaked=$((leaked + 1))
  fi
done
if [[ $leaked -eq 0 ]]; then
  printf 'OK\n'
else
  printf '\nFAILED (%d leaked)\n' "$leaked"
  errors=$((errors + 1))
fi

# 9. Check autogenerated permissions exist for each command
printf '9. Checking autogenerated permissions... '
missing=0
for cmd in $build_commands; do
  if [[ ! -f "apps/lens/permissions/autogenerated/${cmd}.toml" ]]; then
    printf '\n  - missing: %s' "$cmd"
    missing=$((missing + 1))
  fi
done
if [[ $missing -eq 0 ]]; then
  printf 'OK (%d files)\n' "$build_count"
else
  printf '\nFAILED (%d missing)\n' "$missing"
  errors=$((errors + 1))
fi

# 10. Check no stale autogenerated files
printf '10. Checking for stale autogenerated files... '
stale=0
for file in apps/lens/permissions/autogenerated/*.toml; do
  [[ ! -f "$file" ]] && continue
  cmd=$(basename "$file" .toml)
  if ! echo "$build_commands" | grep -q "^${cmd}$"; then
    printf '\n  - stale: %s' "$cmd"
    stale=$((stale + 1))
  fi
done
if [[ $stale -eq 0 ]]; then
  printf 'OK\n'
else
  printf '\nFAILED (%d stale)\n' "$stale"
  errors=$((errors + 1))
fi

# 11. Check detail has no core permissions
printf '11. Checking detail has no core permissions... '
detail_core=$(grep -E '"core:' apps/lens/capabilities/detail.json || true)
if [[ -z "$detail_core" ]]; then
  printf 'OK (no core permissions)\n'
else
  printf 'FAILED (detail has core permissions)\n'
  echo "$detail_core"
  errors=$((errors + 1))
fi

# 12. Check main has minimal core permissions
printf '12. Checking main has minimal core permissions... '
main_core=$(grep -E '"core:' apps/lens/capabilities/main.json | sed 's/.*"\(core:[^"]*\)".*/\1/' | sort)
expected_core="core:event:allow-listen
core:event:allow-unlisten"
if [[ "$main_core" == "$expected_core" ]]; then
  printf 'OK (minimal event permissions)\n'
else
  printf 'FAILED (main has incorrect core permissions)\n'
  echo "Expected:"
  echo "$expected_core"
  echo "Got:"
  echo "$main_core"
  errors=$((errors + 1))
fi

# 13. Validate capability schema via cargo check
printf '13. Validating capability schema... '
cargo_output=$(mktemp)
if cargo check --manifest-path apps/lens/Cargo.toml --quiet >"$cargo_output" 2>&1; then
  printf 'OK (schema valid)\n'
else
  printf 'FAILED (cargo check failed)\n'
  cat "$cargo_output" | head -20
  errors=$((errors + 1))
fi
rm -f "$cargo_output"

# Summary
printf '\n'
if [[ $errors -eq 0 ]]; then
  printf '✓ All capability checks passed\n'
  exit 0
else
  printf '✗ %d capability check(s) failed\n' "$errors"
  exit 1
fi
